function Import-ArtifactData {
    <#
    .SYNOPSIS
        Loads artifact metadata (Name, SizeBytes, CreatedDate, WorkflowId)
        from a JSON fixture file.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
